CREATE TRIGGER bf_calendars_immutable BEFORE UPDATE ON bf_calendars BEGIN SELECT RAISE(ABORT,'immutable_calendar_version'); END;
CREATE TRIGGER bf_rate_sources_immutable BEFORE UPDATE ON bf_rate_sources BEGIN SELECT RAISE(ABORT,'immutable_rate_version'); END;
CREATE TRIGGER bf_schedules_immutable BEFORE UPDATE ON bf_schedules BEGIN SELECT RAISE(ABORT,'immutable_schedule_version'); END;

-- Owner-bound immutable exact answers; source deletion withdraws derived data.
CREATE TABLE bf_query_snapshots (
 id TEXT PRIMARY KEY NOT NULL, owner_id TEXT NOT NULL,
 query_json TEXT NOT NULL CHECK(json_valid(query_json)),
 context_json TEXT NOT NULL CHECK(json_valid(context_json)),
 answer_json TEXT NOT NULL CHECK(json_valid(answer_json)),
 digest TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE bf_query_sources (
 snapshot_id TEXT NOT NULL REFERENCES bf_query_snapshots(id) ON DELETE CASCADE,
 dataset_id TEXT NOT NULL, revision TEXT NOT NULL,
 value_json TEXT NOT NULL CHECK(json_valid(value_json)),
 PRIMARY KEY(snapshot_id,dataset_id)
);
CREATE INDEX bf_query_sources_dataset ON bf_query_sources(dataset_id);
CREATE TABLE bf_query_artifacts (
 id TEXT PRIMARY KEY NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('dashboard','report')),
 snapshot_id TEXT NOT NULL REFERENCES bf_query_snapshots(id) ON DELETE CASCADE,
 title TEXT NOT NULL, owner_id TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TRIGGER bf_query_snapshot_immutable BEFORE UPDATE ON bf_query_snapshots BEGIN SELECT RAISE(ABORT,'immutable_snapshot'); END;
CREATE TRIGGER bf_query_source_immutable BEFORE UPDATE ON bf_query_sources BEGIN SELECT RAISE(ABORT,'immutable_snapshot'); END;
CREATE TRIGGER bf_query_artifact_immutable BEFORE UPDATE ON bf_query_artifacts BEGIN SELECT RAISE(ABORT,'immutable_artifact'); END;

CREATE TABLE bf_file_reviews (
 plan_id TEXT PRIMARY KEY,
 dataset_id TEXT NOT NULL,
 review_json TEXT NOT NULL
);
CREATE INDEX bf_file_reviews_dataset ON bf_file_reviews(dataset_id);

ALTER TABLE rer_dependency_installation ADD COLUMN keys_sealed INTEGER NOT NULL DEFAULT 0 CHECK(keys_sealed IN (0,1));
-- Nonsecret version history lets restored rows name an unavailable retired key
-- without confusing ciphertext tampering or a wrong current secret with restore.
ALTER TABLE rer_dependency_installation ADD COLUMN key_ids TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(key_ids) AND json_type(key_ids)='array');

-- Consent metadata only. Source bytes stay in the reviewed file-door custody.
CREATE TABLE bf_analytics_reads (
 id TEXT NOT NULL,event TEXT NOT NULL CHECK(event IN ('consented','staged','refused','failed')),
 owner TEXT NOT NULL,dataset_id TEXT NOT NULL,fingerprint TEXT NOT NULL,recorded_at TEXT NOT NULL,
 PRIMARY KEY(id,event)
);
CREATE TRIGGER bf_analytics_reads_immutable BEFORE UPDATE ON bf_analytics_reads BEGIN SELECT RAISE(ABORT,'immutable_read_consent'); END;

CREATE TABLE bf_analytics_boards (
 id TEXT PRIMARY KEY NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('dashboard','report')),
 owner_id TEXT NOT NULL,title TEXT NOT NULL,created_at TEXT NOT NULL
);
CREATE TABLE bf_analytics_cards (
 board_id TEXT NOT NULL REFERENCES bf_analytics_boards(id) ON DELETE CASCADE,
 position INTEGER NOT NULL,snapshot_id TEXT NOT NULL REFERENCES bf_query_snapshots(id) ON DELETE CASCADE,
 PRIMARY KEY(board_id,position),UNIQUE(board_id,snapshot_id)
);
-- Withdrawing any retained answer withdraws the whole multi-source artifact.
CREATE TRIGGER bf_analytics_withdraw BEFORE DELETE ON bf_query_snapshots BEGIN
 DELETE FROM bf_analytics_boards WHERE id IN (SELECT board_id FROM bf_analytics_cards WHERE snapshot_id=OLD.id);
END;
CREATE TRIGGER bf_analytics_board_immutable BEFORE UPDATE ON bf_analytics_boards BEGIN SELECT RAISE(ABORT,'immutable_board'); END;
CREATE TRIGGER bf_analytics_card_immutable BEFORE UPDATE ON bf_analytics_cards BEGIN SELECT RAISE(ABORT,'immutable_card'); END;

-- No grant or result bytes: exact consent and acknowledgement metadata only.
CREATE TABLE bf_warehouse_exports (
 id TEXT PRIMARY KEY NOT NULL,owner_id TEXT NOT NULL,board_id TEXT,
 destination_json TEXT NOT NULL CHECK(json_valid(destination_json)),
 fingerprint TEXT NOT NULL,row_count INTEGER NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('review','sending','acknowledged','partial','unknown')),
 created_at TEXT NOT NULL,settled_at TEXT
);
CREATE INDEX bf_warehouse_exports_owner ON bf_warehouse_exports(owner_id,created_at);

-- Immutable semantic revisions; one coherent environment pointer and cache epoch.
CREATE TABLE bf_semantic_models (
 id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, generation INTEGER NOT NULL DEFAULT 0,
 production TEXT, staging TEXT, cache_epoch INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE bf_semantic_revisions (
 id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES bf_semantic_models(id) ON DELETE CASCADE,
 definition_json TEXT NOT NULL CHECK(json_valid(definition_json)), created_at TEXT NOT NULL
);
CREATE TABLE bf_semantic_branches (
 id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES bf_semantic_models(id) ON DELETE CASCADE,
 base_generation INTEGER NOT NULL, revision_id TEXT NOT NULL REFERENCES bf_semantic_revisions(id),
 version INTEGER NOT NULL DEFAULT 1, approval_json TEXT CHECK(approval_json IS NULL OR json_valid(approval_json))
);
CREATE TABLE bf_semantic_history (
 id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES bf_semantic_models(id) ON DELETE CASCADE,
 environment TEXT NOT NULL, revision_id TEXT NOT NULL REFERENCES bf_semantic_revisions(id),
 action TEXT NOT NULL, actor_id TEXT NOT NULL, cache_epoch INTEGER NOT NULL,
 recorded_at TEXT NOT NULL
);
CREATE TABLE bf_semantic_cache (
 model_id TEXT NOT NULL REFERENCES bf_semantic_models(id) ON DELETE CASCADE, environment TEXT NOT NULL, view_id TEXT NOT NULL,
 snapshot_id TEXT NOT NULL REFERENCES bf_query_snapshots(id) ON DELETE CASCADE,
 epoch INTEGER NOT NULL, PRIMARY KEY(model_id,environment,view_id)
);
CREATE TRIGGER bf_semantic_revision_immutable BEFORE UPDATE ON bf_semantic_revisions BEGIN SELECT RAISE(ABORT,'immutable_semantic_revision'); END;
CREATE TRIGGER bf_semantic_history_immutable BEFORE UPDATE ON bf_semantic_history BEGIN SELECT RAISE(ABORT,'immutable_semantic_history'); END;

