 PRIMARY KEY(run_id,reviewer_id)
);
CREATE TRIGGER bf_report_grant_identity_immutable BEFORE UPDATE ON bf_report_reviewer_grants
 WHEN old.id<>new.id OR old.run_id<>new.run_id OR old.owner_id<>new.owner_id OR old.reviewer_id<>new.reviewer_id OR old.artifact_digest<>new.artifact_digest OR old.owner_version<>new.owner_version OR old.reviewer_version<>new.reviewer_version OR old.expires_at<>new.expires_at OR old.created_at<>new.created_at OR old.revoked_at IS NOT NULL AND new.revoked_at IS NOT old.revoked_at
 BEGIN SELECT RAISE(ABORT,'immutable_report_reviewer_grant'); END;
CREATE TRIGGER bf_report_grant_audit_immutable BEFORE UPDATE ON bf_report_grant_audit BEGIN SELECT RAISE(ABORT,'immutable_report_grant_audit'); END;
CREATE TRIGGER bf_report_grant_audit_no_delete BEFORE DELETE ON bf_report_grant_audit BEGIN SELECT RAISE(ABORT,'immutable_report_grant_audit'); END;
-- Native membership changes fence existing sessions and artifact grants at once.
CREATE TRIGGER bf_report_reviewer_membership AFTER UPDATE ON oa_operators WHEN new.version<>old.version OR new.status<>old.status OR new.role<>old.role BEGIN
 INSERT INTO bf_report_grant_audit(id,run_id,grant_id,owner_id,actor_id,reviewer_id,artifact_digest,action,recorded_at)
 SELECT lower(hex(randomblob(16))),run_id,id,owner_id,NULL,reviewer_id,artifact_digest,'membership-revoked',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM bf_report_reviewer_grants WHERE revoked_at IS NULL AND (reviewer_id=new.id OR owner_id=new.id);
 UPDATE bf_report_reviewer_grants SET revoked_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE revoked_at IS NULL AND (reviewer_id=new.id OR owner_id=new.id);
 DELETE FROM bf_report_reviewer_activation WHERE grant_id IN (SELECT id FROM bf_report_reviewer_grants WHERE reviewer_id=new.id OR owner_id=new.id);
 UPDATE bf_report_runs SET state='cancelled',request_json=NULL,artifact_json=NULL,artifact_digest=NULL,approval_json=NULL,version=version+1
 WHERE state IN ('queued','rendered','approved') AND (id IN (SELECT run_id FROM bf_report_pending_recipients WHERE reviewer_id=new.id AND (reviewer_version<>new.version OR new.status<>'active')) OR owner_id=new.id AND (new.status<>'active' OR new.role<>'owner'));
END;
-- Source erasure and explicit cancellation and purge remove controlled authority,
-- while immutable dispatch and minimal audit facts survive unchanged.
CREATE TRIGGER bf_report_reviewer_bytes_withdrawn AFTER UPDATE ON bf_report_runs
 WHEN new.artifact_json IS NULL AND (old.artifact_json IS NOT NULL OR new.request_json IS NULL AND old.request_json IS NOT NULL) BEGIN
 DELETE FROM bf_report_reviewer_grants WHERE run_id=new.id;
 DELETE FROM bf_report_pending_recipients WHERE run_id=new.id;
 DELETE FROM bf_report_downloads WHERE run_id=new.id;
END;

-- Exact view authority is separate from foundation roles and file custody.
CREATE TABLE bf_explore_grants (
 id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, operator_id TEXT NOT NULL,
 model_id TEXT NOT NULL REFERENCES bf_semantic_models(id) ON DELETE CASCADE,
 revision TEXT NOT NULL, view_id TEXT NOT NULL, definition_json TEXT NOT NULL CHECK(json_valid(definition_json)),
 digest TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE INDEX bf_explore_grants_operator ON bf_explore_grants(operator_id);
-- Activation is installation-local and excluded from portable archives.
CREATE TABLE bf_explore_activation (
 grant_id TEXT PRIMARY KEY REFERENCES bf_explore_grants(id) ON DELETE CASCADE,
 owner_version INTEGER NOT NULL, operator_version INTEGER NOT NULL
);
CREATE TABLE bf_explore_audit (
 id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, actor_id TEXT NOT NULL,
 grant_id TEXT NOT NULL, digest TEXT NOT NULL, action TEXT NOT NULL, recorded_at TEXT NOT NULL
);
CREATE TRIGGER bf_explore_membership AFTER UPDATE ON oa_operators WHEN new.version<>old.version OR new.status<>old.status OR new.role<>old.role BEGIN
 DELETE FROM bf_explore_activation WHERE grant_id IN (SELECT id FROM bf_explore_grants WHERE operator_id=new.id OR owner_id=new.id);
END;
CREATE TRIGGER bf_explore_definition_immutable BEFORE UPDATE ON bf_explore_grants BEGIN SELECT RAISE(ABORT,'immutable_exploration_grant'); END;
CREATE TRIGGER bf_explore_audit_immutable BEFORE UPDATE ON bf_explore_audit BEGIN SELECT RAISE(ABORT,'immutable_exploration_audit'); END;

-- Existing activations have no proof that their revisions never changed and
-- returned. Retire them once; a fresh exact owner review issues a new grant.
INSERT INTO bf_explore_audit(id,owner_id,actor_id,grant_id,digest,action,recorded_at)
 SELECT lower(hex(randomblob(16))),g.owner_id,'system',g.id,g.digest,'migration-reapproval-required',strftime('%Y-%m-%dT%H:%M:%fZ','now')
 FROM bf_explore_grants g JOIN bf_explore_activation a ON a.grant_id=g.id;
DELETE FROM bf_explore_activation;

-- Revocation is lasting: restoring a pointer or an imported before-image does
-- not recreate activation. These fences apply to every native mutation door.
CREATE TRIGGER bf_explore_model_revision AFTER UPDATE OF production ON bf_semantic_models
WHEN new.production IS NOT old.production BEGIN
 INSERT INTO bf_explore_audit(id,owner_id,actor_id,grant_id,digest,action,recorded_at)
  SELECT lower(hex(randomblob(16))),g.owner_id,'system',g.id,g.digest,'model-invalidated',strftime('%Y-%m-%dT%H:%M:%fZ','now')
  FROM bf_explore_grants g JOIN bf_explore_activation a ON a.grant_id=g.id WHERE g.model_id=new.id;
 DELETE FROM bf_explore_activation WHERE grant_id IN
  (SELECT id FROM bf_explore_grants WHERE model_id=new.id);
END;
CREATE TRIGGER bf_explore_source_revision AFTER UPDATE ON bf_file_tables
WHEN new.revision IS NOT old.revision OR new.value_json IS NOT old.value_json BEGIN
 INSERT INTO bf_explore_audit(id,owner_id,actor_id,grant_id,digest,action,recorded_at)
  SELECT lower(hex(randomblob(16))),g.owner_id,'system',g.id,g.digest,'source-invalidated',strftime('%Y-%m-%dT%H:%M:%fZ','now')
  FROM bf_explore_grants g JOIN bf_explore_activation a ON a.grant_id=g.id
  WHERE EXISTS(SELECT 1 FROM json_each(g.definition_json,'$.sources') s WHERE json_extract(s.value,'$.id')=old.id);
 DELETE FROM bf_explore_activation WHERE grant_id IN
  (SELECT g.id FROM bf_explore_grants g, json_each(g.definition_json,'$.sources') s
   WHERE json_extract(s.value,'$.id')=old.id);
END;
CREATE TRIGGER bf_explore_source_removed BEFORE DELETE ON bf_file_tables BEGIN
 INSERT INTO bf_explore_audit(id,owner_id,actor_id,grant_id,digest,action,recorded_at)
  SELECT lower(hex(randomblob(16))),g.owner_id,'system',g.id,g.digest,'source-invalidated',strftime('%Y-%m-%dT%H:%M:%fZ','now')
  FROM bf_explore_grants g JOIN bf_explore_activation a ON a.grant_id=g.id
  WHERE EXISTS(SELECT 1 FROM json_each(g.definition_json,'$.sources') s WHERE json_extract(s.value,'$.id')=old.id);
 DELETE FROM bf_explore_activation WHERE grant_id IN
  (SELECT g.id FROM bf_explore_grants g, json_each(g.definition_json,'$.sources') s
   WHERE json_extract(s.value,'$.id')=old.id);
END;

-- Charts retain one immutable native answer; source erasure withdraws both.
CREATE TABLE bf_charts (
 id TEXT PRIMARY KEY NOT NULL,
