);

-- Native interactive limits can be lowered by the current installation owner.
-- An absent singleton is explicit configuration revision zero: CSV 30000,
-- XLSX 150000. No rows, source grants or analytical activations are stored here.
CREATE TABLE bf_explore_export_policy (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 revision INTEGER NOT NULL CHECK(revision>0),
 csv INTEGER NOT NULL CHECK(csv BETWEEN 1 AND 30000),
 xlsx INTEGER NOT NULL CHECK(xlsx BETWEEN 1 AND 150000)
);
CREATE TABLE bf_explore_export_policy_audit (
 revision INTEGER PRIMARY KEY CHECK(revision>0), actor_id TEXT NOT NULL,
 previous_csv INTEGER NOT NULL, previous_xlsx INTEGER NOT NULL,
 csv INTEGER NOT NULL, xlsx INTEGER NOT NULL, recorded_at TEXT NOT NULL
);
CREATE TRIGGER bf_explore_export_policy_audit_immutable BEFORE UPDATE ON bf_explore_export_policy_audit BEGIN SELECT RAISE(ABORT,'immutable_export_policy_audit'); END;

-- Both subjects remain actual native immutable exact-query snapshots. Erasing
-- either source withdraws its snapshot and this controlled derived artifact.
CREATE TABLE bf_exploration_compositions (
 id TEXT PRIMARY KEY, owner_id TEXT NOT NULL,
 left_snapshot TEXT NOT NULL REFERENCES bf_query_snapshots(id) ON DELETE CASCADE,
 right_snapshot TEXT NOT NULL REFERENCES bf_query_snapshots(id) ON DELETE CASCADE,
 definition_json TEXT NOT NULL CHECK(json_valid(definition_json)),
 result_json TEXT NOT NULL CHECK(json_valid(result_json)), digest TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TRIGGER bf_exploration_composition_immutable BEFORE UPDATE ON bf_exploration_compositions BEGIN SELECT RAISE(ABORT,'immutable_exploration_composition'); END;

-- Preserve complete native values while increasing their explicit byte bound.
-- No table references this table through a foreign key. Rebuilding it must not
-- retire grants: source identity, revision and content remain exactly unchanged.
DROP TRIGGER bf_explore_source_revision;
DROP TRIGGER bf_explore_source_removed;

CREATE TABLE bf_file_tables_large (
 id TEXT PRIMARY KEY NOT NULL,
 value_json TEXT NOT NULL CHECK(json_valid(value_json) AND length(CAST(value_json AS BLOB))<=1900000),
 revision TEXT NOT NULL
);
INSERT INTO bf_file_tables_large(id,value_json,revision)
 SELECT id,value_json,revision FROM bf_file_tables;
DROP TABLE bf_file_tables;
ALTER TABLE bf_file_tables_large RENAME TO bf_file_tables;

-- Preserve the lasting source-revision fences from migration 0042.
CREATE TRIGGER bf_explore_source_revision AFTER UPDATE ON bf_file_tables
WHEN new.revision IS NOT old.revision OR new.value_json IS NOT old.value_json BEGIN
 INSERT INTO bf_explore_audit(id,owner_id,actor_id,grant_id,digest,action,recorded_at)
  SELECT lower(hex(randomblob(16))),g.owner_id,'system',g.id,g.digest,'source-invalidated',strftime('%Y-%m-%dT%H:%M:%fZ','now')
  FROM bf_explore_grants g JOIN bf_explore_activation a ON a.grant_id=g.id
  WHERE EXISTS(SELECT 1 FROM json_each(g.definition_json,'$.sources') s WHERE json_extract(s.value,'$.id')=old.id);
 DELETE FROM bf_explore_activation WHERE grant_id IN
  (SELECT g.id FROM bf_explore_grants g, json_each(g.definition_json,'$.sources') s
   WHERE json_extract(s.value,'$.id')=old.id);
END;
CREATE TRIGGER bf_explore_source_removed BEFORE DELETE ON bf_file_tables BEGIN
 INSERT INTO bf_explore_audit(id,owner_id,actor_id,grant_id,digest,action,recorded_at)
  SELECT lower(hex(randomblob(16))),g.owner_id,'system',g.id,g.digest,'source-invalidated',strftime('%Y-%m-%dT%H:%M:%fZ','now')
  FROM bf_explore_grants g JOIN bf_explore_activation a ON a.grant_id=g.id
  WHERE EXISTS(SELECT 1 FROM json_each(g.definition_json,'$.sources') s WHERE json_extract(s.value,'$.id')=old.id);
 DELETE FROM bf_explore_activation WHERE grant_id IN
  (SELECT g.id FROM bf_explore_grants g, json_each(g.definition_json,'$.sources') s
   WHERE json_extract(s.value,'$.id')=old.id);
END;

-- Grid documents and independently editable phone placement bind real retained
-- dashboard boards. Publication moves one pointer; every draft stays immutable.
CREATE TABLE bf_dashboard_definitions (
 id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, head_revision INTEGER NOT NULL CHECK(head_revision>0),
 generation INTEGER NOT NULL DEFAULT 0 CHECK(generation>=0), published_revision INTEGER
);
CREATE TABLE bf_dashboard_definition_revisions (
 dashboard_id TEXT NOT NULL REFERENCES bf_dashboard_definitions(id) ON DELETE CASCADE,
 revision INTEGER NOT NULL CHECK(revision>0), document_json TEXT NOT NULL CHECK(json_valid(document_json)),
 board_id TEXT NOT NULL REFERENCES bf_analytics_boards(id) ON DELETE CASCADE,
 digest TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(dashboard_id,revision)
);
CREATE TABLE bf_dashboard_definition_history (
 id TEXT PRIMARY KEY, dashboard_id TEXT NOT NULL REFERENCES bf_dashboard_definitions(id) ON DELETE CASCADE,
 revision INTEGER NOT NULL, action TEXT NOT NULL CHECK(action IN ('draft','publish','rollback')),
 actor_id TEXT NOT NULL, digest TEXT NOT NULL, recorded_at TEXT NOT NULL
);
CREATE TRIGGER bf_dashboard_definition_revision_immutable BEFORE UPDATE ON bf_dashboard_definition_revisions BEGIN SELECT RAISE(ABORT,'immutable_dashboard_definition_revision'); END;
CREATE TRIGGER bf_dashboard_definition_history_immutable BEFORE UPDATE ON bf_dashboard_definition_history BEGIN SELECT RAISE(ABORT,'immutable_dashboard_definition_history'); END;
-- Withdrawing any constituent board withdraws all its authored versions and
-- publication metadata, including drafts and historical phone placements.
CREATE TRIGGER bf_dashboard_definition_withdraw BEFORE DELETE ON bf_analytics_boards BEGIN
 DELETE FROM bf_dashboard_definitions WHERE id IN (SELECT dashboard_id FROM bf_dashboard_definition_revisions WHERE board_id=OLD.id);
END;

-- Private reader choices never move a dashboard publication pointer.
CREATE TABLE bf_dashboard_bookmarks (
 dashboard_id TEXT NOT NULL, owner_id TEXT NOT NULL, name TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(revision>0 AND revision<=100),
 filters_json TEXT NOT NULL CHECK(json_valid(filters_json)), fields_json TEXT NOT NULL CHECK(json_valid(fields_json)), created_at TEXT NOT NULL,
 PRIMARY KEY(dashboard_id,owner_id,name,revision)
);
CREATE TRIGGER bf_dashboard_bookmark_immutable BEFORE UPDATE ON bf_dashboard_bookmarks BEGIN SELECT RAISE(ABORT,'immutable_dashboard_bookmark'); END;
CREATE TRIGGER bf_dashboard_bookmark_board_withdraw BEFORE DELETE ON bf_analytics_boards BEGIN
 DELETE FROM bf_dashboard_bookmarks WHERE dashboard_id=OLD.id;
END;
CREATE TRIGGER bf_dashboard_bookmark_artifact_withdraw BEFORE DELETE ON bf_query_artifacts BEGIN
 DELETE FROM bf_dashboard_bookmarks WHERE dashboard_id=OLD.id;
END;

-- Curated reporting apps: one owner-edited draft, immutable published versions
-- that freeze their content queries, live audience membership bound to the
-- member's current account version, and member subscription definitions.
CREATE TABLE bf_apps (
 id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, draft_json TEXT NOT NULL CHECK(json_valid(draft_json)),
 draft_revision INTEGER NOT NULL CHECK(draft_revision>0), head_version INTEGER NOT NULL DEFAULT 0 CHECK(head_version>=0),
 published_version INTEGER, created_at TEXT NOT NULL
);
CREATE TABLE bf_app_versions (
 app_id TEXT NOT NULL REFERENCES bf_apps(id) ON DELETE CASCADE, version INTEGER NOT NULL CHECK(version>0),
 document_json TEXT NOT NULL CHECK(json_valid(document_json)), digest TEXT NOT NULL,
 action TEXT NOT NULL CHECK(action IN ('publish','rollback')), restores INTEGER, actor_id TEXT NOT NULL, created_at TEXT NOT NULL,
 PRIMARY KEY(app_id,version)
);
CREATE TABLE bf_app_members (
 app_id TEXT NOT NULL REFERENCES bf_apps(id) ON DELETE CASCADE, audience TEXT NOT NULL,
 operator_id TEXT NOT NULL, operator_version INTEGER NOT NULL, added_at TEXT NOT NULL,
 PRIMARY KEY(app_id,audience,operator_id)
);
CREATE INDEX bf_app_members_operator ON bf_app_members(operator_id);
CREATE TABLE bf_app_subscriptions (
 id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES bf_apps(id) ON DELETE CASCADE, operator_id TEXT NOT NULL,
 audience TEXT NOT NULL, page_key TEXT NOT NULL, created_at TEXT NOT NULL, ended_at TEXT, ended_reason TEXT
);
CREATE INDEX bf_app_subscriptions_operator ON bf_app_subscriptions(operator_id);
CREATE TABLE bf_app_audit (
 id TEXT PRIMARY KEY, app_id TEXT NOT NULL, owner_id TEXT NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL,
 subject TEXT, version INTEGER, digest TEXT, recorded_at TEXT NOT NULL
);
-- Reviewed Power BI app definitions: inactive mappings, never credentials.
CREATE TABLE bf_app_imports (
 id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, value_json TEXT NOT NULL, revision TEXT NOT NULL
);
CREATE TRIGGER bf_app_version_immutable BEFORE UPDATE ON bf_app_versions BEGIN SELECT RAISE(ABORT,'immutable_app_version'); END;
CREATE TRIGGER bf_app_audit_immutable BEFORE UPDATE ON bf_app_audit BEGIN SELECT RAISE(ABORT,'immutable_app_audit'); END;
-- A membership change ends every audience access and subscription of that account;
-- reactivation never revives either.
CREATE TRIGGER bf_app_membership AFTER UPDATE ON oa_operators WHEN new.version<>old.version OR new.status<>old.status OR new.role<>old.role BEGIN
 UPDATE bf_app_subscriptions SET ended_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'),ended_reason='membership-changed' WHERE operator_id=new.id AND ended_at IS NULL;
 DELETE FROM bf_app_members WHERE operator_id=new.id;
END;
-- Installation-local consent, separate from portable definitions and membership.
CREATE TABLE bf_app_activation (
 app_id TEXT PRIMARY KEY REFERENCES bf_apps(id) ON DELETE CASCADE,
 version INTEGER NOT NULL, owner_version INTEGER NOT NULL, expires_at TEXT NOT NULL
);
CREATE TABLE bf_app_version_sources (
 app_id TEXT NOT NULL, version INTEGER NOT NULL, dataset_id TEXT NOT NULL,
 revision TEXT NOT NULL, digest TEXT NOT NULL, PRIMARY KEY(app_id,version,dataset_id)
);
CREATE TABLE bf_app_version_models (
 app_id TEXT NOT NULL, version INTEGER NOT NULL, model_id TEXT NOT NULL,
 revision TEXT NOT NULL, PRIMARY KEY(app_id,version,model_id)
);
CREATE TABLE bf_app_version_metrics (
 app_id TEXT NOT NULL, version INTEGER NOT NULL, metric_id TEXT NOT NULL,
 revision INTEGER NOT NULL, PRIMARY KEY(app_id,version,metric_id)
);
CREATE TRIGGER bf_app_owner_membership AFTER UPDATE ON oa_operators
 WHEN new.version<>old.version OR new.status<>old.status OR new.role<>old.role BEGIN
 DELETE FROM bf_app_activation WHERE app_id IN (SELECT id FROM bf_apps WHERE owner_id=new.id);
END;
CREATE TRIGGER bf_app_source_revision AFTER UPDATE ON bf_file_tables
 WHEN new.revision<>old.revision OR new.value_json<>old.value_json BEGIN
 DELETE FROM bf_app_activation WHERE app_id IN (SELECT app_id FROM bf_app_version_sources WHERE dataset_id=new.id);
END;
CREATE TRIGGER bf_app_source_removed BEFORE DELETE ON bf_file_tables BEGIN
 DELETE FROM bf_app_activation WHERE app_id IN (SELECT app_id FROM bf_app_version_sources WHERE dataset_id=old.id);
END;
CREATE TRIGGER bf_app_model_revision AFTER UPDATE OF production ON bf_semantic_models WHEN new.production IS NOT old.production BEGIN
 DELETE FROM bf_app_activation WHERE app_id IN (SELECT app_id FROM bf_app_version_models WHERE model_id=new.id);
END;
CREATE TRIGGER bf_app_model_removed BEFORE DELETE ON bf_semantic_models BEGIN
 DELETE FROM bf_app_activation WHERE app_id IN (SELECT app_id FROM bf_app_version_models WHERE model_id=old.id);
END;
CREATE TRIGGER bf_app_metric_revision AFTER UPDATE ON bf_metrics
 WHEN new.published_revision IS NOT old.published_revision OR new.deprecated_at IS NOT old.deprecated_at BEGIN
 DELETE FROM bf_app_activation WHERE app_id IN (SELECT app_id FROM bf_app_version_metrics WHERE metric_id=new.id);
END;
CREATE TRIGGER bf_app_metric_removed BEFORE DELETE ON bf_metrics BEGIN
 DELETE FROM bf_app_activation WHERE app_id IN (SELECT app_id FROM bf_app_version_metrics WHERE metric_id=old.id);
END;
-- Pending subscriptions cannot resume automatically after source authority ends.
CREATE TRIGGER bf_app_source_subscription_revision AFTER UPDATE ON bf_file_tables
 WHEN new.revision<>old.revision OR new.value_json<>old.value_json BEGIN
 UPDATE bf_app_subscriptions SET ended_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'),ended_reason='source-authority-changed'
 WHERE ended_at IS NULL AND app_id IN (SELECT app_id FROM bf_app_version_sources WHERE dataset_id=new.id);
END;
CREATE TRIGGER bf_app_source_subscription_removed BEFORE DELETE ON bf_file_tables BEGIN
 UPDATE bf_app_subscriptions SET ended_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'),ended_reason='source-erased'
 WHERE ended_at IS NULL AND app_id IN (SELECT app_id FROM bf_app_version_sources WHERE dataset_id=old.id);
END;
CREATE TRIGGER bf_app_model_subscription_revision AFTER UPDATE OF production ON bf_semantic_models WHEN new.production IS NOT old.production BEGIN
 UPDATE bf_app_subscriptions SET ended_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'),ended_reason='model-authority-changed'
 WHERE ended_at IS NULL AND app_id IN (SELECT app_id FROM bf_app_version_models WHERE model_id=new.id);
END;
-- Short-lived reader context cannot transfer or outlive a published app version.
CREATE TABLE bf_app_dashboard_contexts (
 id TEXT PRIMARY KEY, app_id TEXT NOT NULL, app_version INTEGER NOT NULL, operator_id TEXT NOT NULL,
 audience TEXT NOT NULL, source_page TEXT NOT NULL, target_page TEXT NOT NULL, context_json TEXT NOT NULL, expires_at TEXT NOT NULL
);

-- Personal dashboard choices never move publication pointers or carry authority.
CREATE TABLE bf_dashboard_reader_bookmarks (
 dashboard_id TEXT NOT NULL REFERENCES bf_dashboard_definitions(id) ON DELETE CASCADE,
 operator_id TEXT NOT NULL, scope_id TEXT NOT NULL DEFAULT 'native', name TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0),
 published_revision INTEGER NOT NULL, selection_json TEXT NOT NULL CHECK(json_valid(selection_json)), created_at TEXT NOT NULL,
 PRIMARY KEY(dashboard_id,operator_id,scope_id,name,revision)
);
CREATE TRIGGER bf_dashboard_reader_bookmark_immutable BEFORE UPDATE ON bf_dashboard_reader_bookmarks BEGIN SELECT RAISE(ABORT,'immutable_dashboard_reader_bookmark'); END;
-- Named drillthrough context is exact, short-lived, audience-local and carries
-- only filter definitions. Every destination read still needs current authority.
CREATE TABLE bf_dashboard_reader_contexts (
 id TEXT PRIMARY KEY, operator_id TEXT NOT NULL,
 source_id TEXT NOT NULL REFERENCES bf_dashboard_definitions(id) ON DELETE CASCADE,
 source_revision INTEGER NOT NULL, target_id TEXT NOT NULL REFERENCES bf_dashboard_definitions(id) ON DELETE CASCADE,
 target_revision INTEGER NOT NULL, context_json TEXT NOT NULL CHECK(json_valid(context_json)), expires_at TEXT NOT NULL
);
CREATE TRIGGER bf_dashboard_reader_membership AFTER UPDATE ON oa_operators WHEN new.version<>old.version OR new.status<>old.status OR new.role<>old.role BEGIN
 DELETE FROM bf_dashboard_reader_contexts WHERE operator_id=new.id;
 DELETE FROM bf_dashboard_reader_bookmarks WHERE operator_id=new.id;
END;

-- Local completed erasure work has no retained actor or subject identity.
CREATE TABLE bf_erasure_audit (
 id TEXT PRIMARY KEY, actor_ref TEXT NOT NULL, subject_ref TEXT NOT NULL, recorded_at TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('source_erasure','retention_changed'))
);
CREATE TABLE bf_erasure_stores (
 audit_id TEXT NOT NULL REFERENCES bf_erasure_audit(id), store TEXT NOT NULL, rows INTEGER NOT NULL CHECK(rows>=0),
 PRIMARY KEY(audit_id,store)
);
CREATE TRIGGER bf_erasure_audit_immutable BEFORE UPDATE ON bf_erasure_audit BEGIN SELECT RAISE(ABORT,'immutable_erasure_audit'); END;
CREATE TRIGGER bf_erasure_audit_permanent BEFORE DELETE ON bf_erasure_audit BEGIN SELECT RAISE(ABORT,'permanent_erasure_audit'); END;
CREATE TRIGGER bf_erasure_stores_immutable BEFORE UPDATE ON bf_erasure_stores BEGIN SELECT RAISE(ABORT,'immutable_erasure_store'); END;
CREATE TRIGGER bf_erasure_stores_permanent BEFORE DELETE ON bf_erasure_stores BEGIN SELECT RAISE(ABORT,'permanent_erasure_store'); END;
CREATE TABLE bf_cost_budgets (
 scope TEXT NOT NULL CHECK(scope IN ('source','job','agent','tenant')), id TEXT NOT NULL,
 revision TEXT NOT NULL, limit_micro INTEGER NOT NULL CHECK(limit_micro>=0), warn_micro INTEGER NOT NULL CHECK(warn_micro>=0 AND warn_micro<=limit_micro),
 PRIMARY KEY(scope,id)
);
CREATE TABLE bf_cost_reservations (
 id TEXT PRIMARY KEY, scope TEXT NOT NULL, budget_id TEXT NOT NULL,
 estimated_micro INTEGER NOT NULL CHECK(estimated_micro>=0), actual_micro INTEGER CHECK(actual_micro>=0),
 state TEXT NOT NULL CHECK(state IN ('reserved','settled','released')), created_at TEXT NOT NULL,
 FOREIGN KEY(scope,budget_id) REFERENCES bf_cost_budgets(scope,id)
);
CREATE TABLE bf_cost_audit (
 id TEXT PRIMARY KEY, actor TEXT NOT NULL, kind TEXT NOT NULL, record_id TEXT NOT NULL, created_at TEXT NOT NULL
);
-- Minimum retention and legal holds never schedule automatic destruction.
CREATE TABLE bf_source_retention (
 dataset_id TEXT PRIMARY KEY, revision TEXT NOT NULL, legal_hold INTEGER NOT NULL CHECK(legal_hold IN (0,1)), minimum_retain_until TEXT
);
CREATE TRIGGER bf_erasure_audit_no_replace BEFORE INSERT ON bf_erasure_audit WHEN EXISTS(SELECT 1 FROM bf_erasure_audit WHERE id=new.id) BEGIN SELECT RAISE(ABORT,'immutable_erasure_audit'); END;
CREATE TRIGGER bf_erasure_stores_no_replace BEFORE INSERT ON bf_erasure_stores WHEN EXISTS(SELECT 1 FROM bf_erasure_stores WHERE audit_id=new.audit_id AND store=new.store) BEGIN SELECT RAISE(ABORT,'immutable_erasure_store'); END;
-- This routing row exists only inside the guarded retirement batch. The kit's
-- final journal insertion copies its completed counts then removes the route.
CREATE TABLE bf_erasure_pending (
 destination TEXT PRIMARY KEY, audit_id TEXT NOT NULL REFERENCES bf_erasure_audit(id)
);
CREATE TRIGGER bf_erasure_completed_custody AFTER INSERT ON ik_d1_erasure_journal WHEN EXISTS(SELECT 1 FROM bf_erasure_pending WHERE destination=new.destination) BEGIN
 INSERT INTO bf_erasure_stores(audit_id,store,rows)
 SELECT p.audit_id,json_extract(j.value,'$.store'),json_extract(j.value,'$.rows')
 FROM bf_erasure_pending p,json_each(new.stores_json) j WHERE p.destination=new.destination;
 DELETE FROM bf_erasure_pending WHERE destination=new.destination;
END;

CREATE TABLE bf_machine_credentials (
 id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, owner_version INTEGER NOT NULL,
 token_hash TEXT NOT NULL UNIQUE, definition_json TEXT NOT NULL, digest TEXT NOT NULL,
 expires_at TEXT NOT NULL, max_operations INTEGER NOT NULL, used_operations INTEGER NOT NULL DEFAULT 0,
 revoked INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL
);
CREATE TABLE bf_machine_audit (
 id TEXT PRIMARY KEY, credential_id TEXT NOT NULL, owner_id TEXT NOT NULL,
 actor_kind TEXT NOT NULL, action TEXT NOT NULL, recorded_at TEXT NOT NULL
);
CREATE INDEX bf_machine_audit_owner ON bf_machine_audit(owner_id,recorded_at);
-- Authority withdrawal is permanent; a later rollback never revives an old key.
CREATE TRIGGER bf_machine_model_withdrawal AFTER UPDATE OF production ON bf_semantic_models
WHEN OLD.production IS NOT NEW.production BEGIN
 UPDATE bf_machine_credentials SET revoked=1 WHERE json_extract(definition_json,'$.modelId')=OLD.id;
END;
CREATE TRIGGER bf_machine_model_removal AFTER DELETE ON bf_semantic_models BEGIN
 UPDATE bf_machine_credentials SET revoked=1 WHERE json_extract(definition_json,'$.modelId')=OLD.id;
END;
CREATE TRIGGER bf_machine_source_withdrawal AFTER UPDATE ON bf_file_tables BEGIN
 UPDATE bf_machine_credentials SET revoked=1 WHERE EXISTS(
  SELECT 1 FROM json_each(definition_json,'$.sources') s WHERE json_extract(s.value,'$.id')=OLD.id
 );
END;
CREATE TRIGGER bf_machine_source_removal AFTER DELETE ON bf_file_tables BEGIN
 UPDATE bf_machine_credentials SET revoked=1 WHERE EXISTS(
  SELECT 1 FROM json_each(definition_json,'$.sources') s WHERE json_extract(s.value,'$.id')=OLD.id
 );
END;
CREATE TRIGGER bf_machine_principal_withdrawal AFTER UPDATE OF version,status,role ON oa_operators
WHEN OLD.version IS NOT NEW.version OR OLD.status IS NOT NEW.status OR OLD.role IS NOT NEW.role BEGIN
 UPDATE bf_machine_credentials SET revoked=1 WHERE owner_id=OLD.id;
END;

CREATE TABLE bf_machine_source_rules (
 dataset_id TEXT PRIMARY KEY, version INTEGER NOT NULL,
 definition_json TEXT NOT NULL CHECK(json_valid(definition_json)), digest TEXT NOT NULL
);
CREATE TRIGGER bf_machine_source_policy_insert AFTER INSERT ON bf_machine_source_rules BEGIN
 UPDATE bf_machine_credentials SET revoked=1 WHERE EXISTS(
  SELECT 1 FROM json_each(definition_json,'$.sources') s WHERE json_extract(s.value,'$.id')=NEW.dataset_id
 );
END;
CREATE TRIGGER bf_machine_source_policy_update AFTER UPDATE ON bf_machine_source_rules BEGIN
 UPDATE bf_machine_credentials SET revoked=1 WHERE EXISTS(
  SELECT 1 FROM json_each(definition_json,'$.sources') s WHERE json_extract(s.value,'$.id')=NEW.dataset_id
 );
END;
CREATE TRIGGER bf_machine_source_policy_delete AFTER DELETE ON bf_machine_source_rules BEGIN
 UPDATE bf_machine_credentials SET revoked=1 WHERE EXISTS(
  SELECT 1 FROM json_each(definition_json,'$.sources') s WHERE json_extract(s.value,'$.id')=OLD.dataset_id
 );
END;
CREATE TRIGGER bf_machine_principal_removal BEFORE DELETE ON oa_operators BEGIN
 UPDATE bf_machine_credentials SET revoked=1 WHERE owner_id=OLD.id;
END;
CREATE TRIGGER bf_machine_retirement_audit AFTER UPDATE OF revoked ON bf_machine_credentials
WHEN OLD.revoked=0 AND NEW.revoked=1 BEGIN
 INSERT INTO bf_machine_audit(id,credential_id,owner_id,actor_kind,action,recorded_at)
 VALUES(lower(hex(randomblob(16))),NEW.id,NEW.owner_id,'machine','activation-retired',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
END;
CREATE TRIGGER bf_machine_source_policy_erasure AFTER DELETE ON bf_file_tables BEGIN
 DELETE FROM bf_machine_source_rules WHERE dataset_id=OLD.id;
END;

CREATE TABLE bf_collaboration_subjects (
 key TEXT PRIMARY KEY, kind TEXT NOT NULL, target_id TEXT NOT NULL, owner_id TEXT NOT NULL,
 fingerprint TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE bf_collaboration_sources (
 subject_key TEXT NOT NULL REFERENCES bf_collaboration_subjects(key) ON DELETE CASCADE,
 dataset_id TEXT NOT NULL, PRIMARY KEY(subject_key,dataset_id)
);
CREATE TABLE bf_collaboration_comments (
 id TEXT PRIMARY KEY, subject_key TEXT NOT NULL REFERENCES bf_collaboration_subjects(key) ON DELETE CASCADE,
 author_id TEXT NOT NULL, body TEXT NOT NULL, point INTEGER, created_at TEXT NOT NULL
);
CREATE TABLE bf_collaboration_links (
 id TEXT PRIMARY KEY, subject_key TEXT NOT NULL REFERENCES bf_collaboration_subjects(key) ON DELETE CASCADE,
 issuer_id TEXT NOT NULL, issuer_version INTEGER NOT NULL, recipient_id TEXT NOT NULL, recipient_version INTEGER NOT NULL,
 expires_at TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL
);
CREATE TABLE bf_collaboration_notifications (
 id TEXT PRIMARY KEY, comment_id TEXT NOT NULL REFERENCES bf_collaboration_comments(id) ON DELETE CASCADE,
 link_id TEXT NOT NULL REFERENCES bf_collaboration_links(id) ON DELETE CASCADE,
 recipient_id TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE bf_collaboration_annotations (
 id TEXT PRIMARY KEY, metric_id TEXT NOT NULL, revision INTEGER NOT NULL, digest TEXT NOT NULL,
 point TEXT NOT NULL, body TEXT NOT NULL, author_id TEXT NOT NULL, created_at TEXT NOT NULL,
 FOREIGN KEY(metric_id,revision) REFERENCES bf_metric_revisions(metric_id,revision) ON DELETE CASCADE
);
CREATE TABLE bf_collaboration_audit (
 id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, resource_id TEXT NOT NULL, recorded_at TEXT NOT NULL
);
CREATE TRIGGER bf_collaboration_source_changed AFTER UPDATE ON bf_file_tables BEGIN
 UPDATE bf_collaboration_subjects SET active=0 WHERE key IN (SELECT subject_key FROM bf_collaboration_sources WHERE dataset_id=NEW.id);
 UPDATE bf_collaboration_links SET revoked=1 WHERE subject_key IN (SELECT subject_key FROM bf_collaboration_sources WHERE dataset_id=NEW.id);
END;
CREATE TRIGGER bf_collaboration_source_erased BEFORE DELETE ON bf_file_tables BEGIN
 DELETE FROM bf_collaboration_subjects WHERE key IN (SELECT subject_key FROM bf_collaboration_sources WHERE dataset_id=OLD.id);
END;
CREATE TRIGGER bf_collaboration_membership AFTER UPDATE ON oa_operators
WHEN NEW.version<>OLD.version OR NEW.status<>OLD.status OR NEW.role<>OLD.role BEGIN
 UPDATE bf_collaboration_links SET revoked=1 WHERE issuer_id=NEW.id OR recipient_id=NEW.id;
END;
CREATE TRIGGER bf_collaboration_member_removed BEFORE DELETE ON oa_operators BEGIN
 UPDATE bf_collaboration_links SET revoked=1 WHERE issuer_id=OLD.id OR recipient_id=OLD.id;
END;

CREATE TABLE bf_entitlement_snapshots (
